import{_ as t,o,c as d,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Help Desk Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Help Desk Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/help-desk-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Help Desk Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/help-desk-overview"}]]},"headers":[],"relativePath":"user-guide/help-desk-overview.md","filePath":"user-guide/help-desk-overview.md","lastUpdated":1787698014000}'),i={name:"user-guide/help-desk-overview.md"};function n(s,e,r,l,c,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="help-desk-module" tabindex="-1">Help Desk Module <a class="header-anchor" href="#help-desk-module" aria-label="Permalink to &quot;Help Desk Module&quot;">​</a></h1><p>Operations module on the frozen platform. An internal ticketing MVP — number, subject, description, tenant-managed category, priority, status workflow, assignment, notes, activity timeline, optional due date, and KPIs — with <strong>soft, optional</strong> links to Contacts and Companies. Unlike many CRM modules that hard-depend on Contacts, Help Desk is <strong>standalone</strong>: it installs with no module dependencies and works fully on its own.</p><blockquote><p><strong>Not Central Feedback</strong></p><p><a href="/user-guide/feedback">Give Feedback</a> is the platform bug/feature intake flow (Tenant submit → Central triage). Help Desk is a <strong>tenant-scoped</strong> internal support queue for your workspace team — distinct product, permissions, and data model.</p></blockquote><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/help-desk">help-desk.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/help-desk">help-desk-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/help-desk">help-desk-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/expenses-overview">expenses-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-help-desk">../api/tenant-v1-help-desk.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Header ticket: number (<code>HD-</code> prefix, configurable), subject, description, tenant-managed category, priority (<code>low</code> / <code>medium</code> / <code>high</code> / <code>urgent</code>), status, optional <code>due_at</code></li><li>Optional <code>contact_id</code> and <code>company_id</code> — soft links, only validated (and only pickable in the UI) when the corresponding module is entitled on the workspace</li><li>Optional <strong>Knowledge Base</strong> article links (soft M2M) when <code>knowledge-base</code> is entitled — pick published articles (or drafts when the actor has <code>knowledge-base.update</code>); backlinks on article view when Help Desk is entitled</li><li>Status workflow: <code>open → in_progress | waiting | resolved | closed</code>; <code>resolved → closed | open</code>; <code>closed → open</code></li><li>Content edits blocked when status is <strong>Closed</strong> — use status actions, assignment, and notes instead</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>help-desk.assign</code></li><li>Notes (comments) + activity timeline; optional <strong>attachments</strong> on ticket create and note replies (counts toward <a href="/user-guide/storage-overview">Storage</a> quota)</li><li>Table view with search, status/priority/category filters, assignee filter, overdue filter, and <strong>My Tickets</strong> toggle; <strong>Manage categories</strong> dialog (same <code>help-desk.*</code> permissions as ticket CRUD)</li><li>KPIs via <code>GET /help-desk/stats</code> (total, mine, open, in progress, waiting, resolved, closed, overdue)</li><li>Dashboard widget <code>help_desk_my_open</code> (module + <code>help-desk.view</code>; assignee-scoped like list)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:help-desk</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, no hard dependencies</li><li>In-app notifications on assignment, close, and reopen</li><li>Audit + activity logging</li><li><code>due_at</code> stored in UTC; overdue KPIs and filters use workspace timezone convention (see <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone</a>)</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>help-desk.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>close</code> · <code>reopen</code></p><table tabindex="0"><thead><tr><th>Role</th><th>Grants</th></tr></thead><tbody><tr><td><strong>admin</strong></td><td>All except <code>force.delete</code></td></tr><tr><td><strong>manager</strong></td><td><code>view</code>, <code>create</code>, <code>update</code>, <code>assign</code>, <code>close</code>, <code>reopen</code></td></tr><tr><td><strong>staff</strong></td><td><code>view</code>, <code>create</code>, <code>update</code>, <code>close</code>, <code>reopen</code></td></tr></tbody></table><p>Enable Help Desk from Marketplace (free) — it has no hard dependencies, so it can be installed on its own, before or after Contacts / Companies. Catalog: slug <code>help-desk</code>, category <code>operations</code> (Operations), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 10</code>, version <strong>1.2.0</strong>.</p><h2 id="why-standalone-soft-dependencies" tabindex="-1">Why standalone (soft dependencies) <a class="header-anchor" href="#why-standalone-soft-dependencies" aria-label="Permalink to &quot;Why standalone (soft dependencies)&quot;">​</a></h2><p>Most internal tickets (IT requests, billing questions) do not require a CRM contact or company record. Both links are optional and only appear once the related module is installed. This keeps Help Desk usable as a lightweight, install-anywhere operations module rather than forcing the full CRM stack.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>SLAs and SLA breach automation</li><li>Email ingest / multi-channel intake (email, chat, social)</li><li>Customer portal (external submit / track)</li><li><code>@mentions</code> in notes</li><li>Automation module triggers for Help Desk events</li><li>Communication Template context for ticket replies</li><li>Kanban board view</li></ul>',15)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
